def unique_records(records, key):
    seen = set()
    result = []
    for record in records:
        val = record[key]
        # Handle unhashable types by using a tuple of the value's representation
        if isinstance(val, (list, dict)):
            val = tuple(val.items()) if isinstance(val, dict) else tuple(val)
        if val not in seen:
            seen.add(val)
            result.append(record)
    return result
